def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    moves = []
    for move in s:
        if move == 'N':
            y += 1
        elif move == 'S':
            y -= 1
        elif move == 'E':
            x += 1
        elif move == 'W':
            x -= 1
        # Save each position's coordinates
        moves.append((x, y))

    max_distance = abs(x) + abs(y)
    # Calculate maximum distance considering k changes
    for i in range(len(moves)):
        current_x, current_y = moves[i]
        # Calculate max distance if we can change k moves up to this point
        # Going back k changes, for every change we can make to maximize the distance
        for j in range(1, k + 1):
            if i - j >= 0:
                changed_x, changed_y = moves[i - j]
                max_distance = max(max_distance, abs(current_x - changed_x) + abs(current_y - changed_y))
    return max_distance
